WITH filtered AS (SELECT id, supplier_name, country, rating, CONCAT_WS('/', supplier_name, city) AS supplier_name_city_key, CONCAT_WS('-', country, city) AS country_city_key, COALESCE(city, 'NONE') AS resolved_city FROM suppliers WHERE city <> 'London'), enriched AS (SELECT *, SUM(rating) OVER (PARTITION BY country ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_rating, MAX(rating) OVER (PARTITION BY country ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_rating, COUNT(rating) OVER (PARTITION BY country ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_rating, MIN(rating) OVER (PARTITION BY country ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_rating FROM filtered), kept_keys AS (SELECT country FROM enriched EXCEPT SELECT country FROM suppliers WHERE rating < 3.5), reconciled AS (SELECT s.* FROM enriched s INNER JOIN kept_keys k ON s.country = k.country), with_windows AS (SELECT id, country, rating, supplier_name_city_key, country_city_key, resolved_city, running_count_rating, RANK() OVER (PARTITION BY country ORDER BY running_sum_rating DESC) AS running_sum_rating_rank, DENSE_RANK() OVER (PARTITION BY country ORDER BY running_count_rating DESC) AS running_count_rating_dense_rank FROM reconciled WHERE country IN ('US', 'DE', 'TH')), kept AS (SELECT s.* FROM with_windows s WHERE EXISTS (SELECT 1 FROM products x WHERE x.supplier_id = s.id AND x.cost <= 300)), not_flagged AS (SELECT s.* FROM kept s WHERE NOT EXISTS (SELECT 1 FROM products c WHERE c.supplier_id = s.id AND c.category NOT IN ('Fashion', 'Home', 'Sports'))), enriched_suppliers AS (SELECT *, RANK() OVER (ORDER BY running_count_rating NULLS LAST) AS running_count_rating_rank, ROUND(rating / SUM(rating) OVER (PARTITION BY country), 4) AS rating_share FROM not_flagged) SELECT id, country, rating, country_city_key, resolved_city, running_sum_rating_rank, running_count_rating_rank, rating_share, CASE WHEN country RLIKE '^(UK|JP)$' THEN 'CORE' ELSE 'PRIORITY' END AS country_zone FROM enriched_suppliers ORDER BY id DESC NULLS LAST;
